    s.sessions[token] = { email, at: Date.now() };
    out = { ok: true, token, profile: { name: u.name, email, phone: u.phone }, board: boardFor(s, email) };
  } else if (action === 'board' || action === 'tick') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada. Entre de novo.');
    const draw = getOpenDraw(s);
    if (new Date(draw.scheduledAt).getTime() <= Date.now()) runDraw(s, draw, false);
    out = { ok: true, profile: { name: u.name, email: u.email, phone: u.phone }, board: boardFor(s, u.email) };
  } else if (action === 'reserve') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada.');
    const draw = getOpenDraw(s);
    if (draw.status !== 'open') throw new Error('Sorteio fechado.');
    const nums = [...new Set((body.animalNumbers||[]).map(Number).filter(n => n>=1 && n<=36))];
    if (!nums.length) throw new Error('Escolhe pelo menos um bicho.');
    const failures = [];
    for (const n of nums) {
      const mine = s.tickets.find(t => t.email===u.email && t.drawId===draw.id && t.animalNumber===n);
      if (mine) continue;
      const clash = s.tickets.find(t => t.drawId===draw.id && t.animalNumber===n && ['cart','awaiting_pix','paid'].includes(t.status));
      if (clash) {
        const sug = recommend(taken(s, draw.id), n);
        failures.push({ number: n, suggestion: sug ? sug.n : null, suggestionName: sug ? sug.name : null });
        continue;
      }
      s.tickets.push({ id: nextId(s), email: u.email, drawId: draw.id, animalNumber: n, status: 'cart', priceCents: PRICE, pixTxid: null, paidAt: null });
    }
    out = { ok: failures.length===0, failures, board: boardFor(s, u.email) };
  } else if (action === 'drop') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada.');
    s.tickets = s.tickets.filter(t => !(t.id===Number(body.ticketId) && t.email===u.email && ['cart','awaiting_pix'].includes(t.status)));
    out = { ok: true, board: boardFor(s, u.email) };
  } else if (action === 'pix') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada.');
    const draw = getOpenDraw(s);
    const rows = s.tickets.filter(t => t.email===u.email && t.drawId===draw.id && ['cart','awaiting_pix'].includes(t.status));
    if (!rows.length) throw new Error('Carrinho vazio.');
    const total = rows.reduce((a,t)=>a+t.priceCents,0);
    const txid = 'SIM'+Date.now().toString(36).toUpperCase();
    rows.forEach(t => { t.status='awaiting_pix'; t.pixTxid=txid; });
    out = { ok: true, payload: pix(txid, total), totalCents: total, board: boardFor(s, u.email) };
  } else if (action === 'pay') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada.');
    const draw = getOpenDraw(s);
    const rows = s.tickets.filter(t => t.email===u.email && t.drawId===draw.id && t.status==='awaiting_pix');
    if (!rows.length) throw new Error('Pagamento ainda não disponível.');
    rows.forEach(t => { t.status='paid'; t.paidAt=new Date().toISOString(); });
    out = { ok: true, board: boardFor(s, u.email) };
  } else if (action === 'forceDraw') {
    const u = tokenUser(s, body.token);
    if (!u) throw new Error('Sessão expirada.');
    const waiting = s.tickets.find(t => t.email===u.email && t.status==='paid' && s.draws.find(d=>d.id===t.drawId && d.status==='open'));
    const draw = waiting ? s.draws.find(d=>d.id===waiting.drawId) : getOpenDraw(s);
    runDraw(s, draw, true);
    out = { ok: true, board: boardFor(s, u.email) };
  } else if (action === 'scheduledDraw') {
    for (const d of s.draws.filter(x => x.status==='open' && new Date(x.scheduledAt).getTime()<=Date.now())) runDraw(s, d, false);
    getOpenDraw(s);
    out = { ok: true, draws: s.draws.slice(-5) };
  } else {
    throw new Error('Ação desconhecida.');
  }
} catch (e) {
  out = { ok: false, error: e.message };
}
return [{ json: out }];

const crypto = require('crypto');
const s = $getWorkflowStaticData('global');
if (!s.draws) s.draws = [];
if (!s.tickets) s.tickets = [];
if (!s.seq) s.seq = 1;
const now = Date.now();
for (const d of s.draws.filter(x => x.status==='open' && new Date(x.scheduledAt).getTime()<=now)) {
  const n = crypto.randomBytes(4).readUInt32BE(0);
  d.status='drawn';
  d.winningNumber=(n%36)+1;
  d.drawnAt=new Date().toISOString();
}
let open = s.draws.find(d => d.status==='open');
if (!open) {
  const sp = new Date(Date.now() - 180*60*1000);
  let t = Date.UTC(sp.getUTCFullYear(), sp.getUTCMonth(), sp.getUTCDate(), 21,0,0,0);
  if (t <= Date.now()) t += 86400000;
  open = { id: ++s.seq, scheduledAt: new Date(t).toISOString(), status:'open', winningNumber:null, drawnAt:null };
  s.draws.push(open);
  for (const n of [3,7,11,16,22,28,32,35]) {
    s.tickets.push({ id: ++s.seq, email:'house', drawId: open.id, animalNumber:n, status:'paid', priceCents:500, pixTxid:'HOUSE-'+n });
  }
}
return [{ json: { ok: true, open, lastDrawn: s.draws.filter(d=>d.status==='drawn').slice(-1)[0] || null } }];
